; Test tune for tests/tx_test.py: a tiny row player at LOAD (default $1000).
; Data comes from tx_tune_data.inc (generated by the test): per song a row
; table (3 voices x (note+1 | 0 hold | $ff gate off, instrument)), speed,
; row count; instruments (wave, AD, SR, PW lo/hi, kind, gate length).
; kind 0: plain; 1: drum (first frame noise $81 one octave up, then the
; instrument); 2: test bit on the first frame ($09), then the instrument.
; Hard restart: gate off on the last frame of a row before a note.
; CIA != 0: init writes LATCH to CIA1 timer A. WILD != 0: init zeroes WILD..WILD+2.

        .include "tx_tune_data.inc"

rowp    = $fb                   ; zero page on purpose: the transcriber must keep it apart

        * = LOAD
        jmp init
        jmp play

init    tax
        lda sp_lo,x
        sta rowp
        lda sp_hi,x
        sta rowp+1
        lda s_speed,x
        sta speed
        lda s_rows,x
        sta nrows
        lda #0
        sta fc
        sta row
        sta ctl
        sta ctl+1
        sta ctl+2
        ldx #$17
-       sta $d400,x
        dex
        bpl -
        lda #$0f
        sta $d418
        .if WILD
        lda #0                  ; RAM outside the load range (like Comic Bakery's $c008)
        sta WILD
        sta WILD+1
        sta WILD+2
        .endif
        .if CIA
        lda #<LATCH
        sta $dc04
        lda #>LATCH
        sta $dc05
        .endif
        rts

play    lda row
        cmp nrows
        bcc +
        rts
+       ldx #0                  ; voice
_v      txa
        asl
        tay                     ; row offset
        lda voff,x
        sta vo
        lda fc
        bne _later
        ; first frame of the row
        lda (rowp),y
        sta vnote,x
        beq _next
        cmp #$ff
        bne _note
        lda ctl,x               ; gate off
        and #$fe
        sta ctl,x
        jsr wctl
        jmp _next
_note   iny
        lda (rowp),y
        sta vins,x
        tay
        lda i_ad,y
        stx t_x
        ldx vo
        sta $d405,x
        lda i_sr,y
        sta $d406,x
        lda i_pwlo,y
        sta $d402,x
        lda i_pwhi,y
        sta $d403,x
        ldx t_x
        lda i_kind,y
        cmp #1
        bne +
        lda vnote,x             ; drum: an octave up, noise
        clc
        adc #12
        jsr wfreq
        lda #$81
        bne _ctl
+       cmp #2
        bne +
        lda vnote,x
        jsr wfreq
        lda #$09                ; test bit first
        bne _ctl
+       lda vnote,x
        jsr wfreq
        lda i_wave,y
        ora #1
_ctl    sta ctl,x
        jsr wctl
        jmp _next
_later  lda vnote,x             ; later frames of a row with a note
        beq _hr
        cmp #$ff
        beq _hr
        ldy vins,x
        lda fc
        cmp #1
        bne +
        lda i_kind,y            ; second frame: the real note / waveform
        beq +
        lda vnote,x
        jsr wfreq
        lda i_wave,y
        ora #1
        sta ctl,x
        jsr wctl
+       lda i_glen,y            ; gate length
        beq _hr
        cmp fc
        bne _hr
        lda ctl,x
        and #$fe
        sta ctl,x
        jsr wctl
_hr     lda fc                  ; last frame: gate off if the next row has a note
        clc
        adc #1
        cmp speed
        bne _next
        txa
        asl
        clc
        adc #6
        tay
        lda (rowp),y
        beq _next
        cmp #$ff
        beq _next
        lda ctl,x
        and #$fe
        sta ctl,x
        jsr wctl
_next   inx
        cpx #3
        beq +
        jmp _v
+       inc fc
        lda fc
        cmp speed
        bne +
        lda #0
        sta fc
        inc row
        lda rowp
        clc
        adc #6
        sta rowp
        bcc +
        inc rowp+1
+       rts

; A = note+1 -> frequency of voice X
wfreq   stx t_x
        sty t_y
        tay
        ldx vo
        lda f_lo-1,y
        sta $d400,x
        lda f_hi-1,y
        sta $d401,x
        ldx t_x
        ldy t_y
        rts

; ctl of voice X -> SID
wctl    stx t_x
        lda ctl,x
        ldx vo
        sta $d404,x
        ldx t_x
        rts

voff    .byte 0, 7, 14
speed   .byte 0
nrows   .byte 0
fc      .byte 0
row     .byte 0
vo      .byte 0
t_x     .byte 0
t_y     .byte 0
ctl     .fill 3
vnote   .fill 3
vins    .fill 3

        .include "tx_tune_tables.inc"
